  ('Lake John', 'Lake', 'freshwater'::public.water_type_enum, ST_SetSRID(ST_MakePoint(-106.46575006899593, 40.777341499038506), 4326)::extensions.geography),
  ('Williams Fork Reservoir', 'Lake', 'freshwater'::public.water_type_enum, ST_SetSRID(ST_MakePoint(-106.21107555573536, 40.01432770915449), 4326)::extensions.geography),
  ('Boettcher Lake', 'Lake', 'freshwater'::public.water_type_enum, ST_SetSRID(ST_MakePoint(-106.51462858360843, 40.82515861389641), 4326)::extensions.geography),
  ('Roxy Ann Lake', 'Lake', 'freshwater'::public.water_type_enum, ST_SetSRID(ST_MakePoint(-106.65405862323652, 40.671647660686006), 4326)::extensions.geography)
) AS v(name, category, water_type, coordinates)
WHERE NOT EXISTS (
  SELECT 1
  FROM public.locations l
  WHERE lower(trim(l.name)) = lower(trim(v.name))
    AND ST_DWithin(
      l.coordinates,
      v.coordinates,
      250
    )
);
